# Generated by Cursor (plan: concatenated words missing space). Edited by Cursor (dictionary via english-words).
"""Scan for tokens not in dictionary that split into two valid parts (word+word or word+ordinal)."""

import re

from scripts.dictionary_loader import get_english_dictionary, is_valid_word_for_rules

WORD_RE = re.compile(r"\b(\w+)\b")
ORDINAL_SUFFIX_RE = re.compile(r"^\d+(?:st|nd|rd|th)$", re.IGNORECASE)
MAX_TOKEN_LEN = 20


def _valid_right_part(word: str, dic: object) -> bool:
    """Return True if word is ordinal (18th), all digits, or valid for rules. Cheap checks first. Edited by Cursor."""
    if ORDINAL_SUFFIX_RE.fullmatch(word):
        return True
    if word.isdigit():
        return True
    return is_valid_word_for_rules(word, dic)  # type: ignore[arg-type]


def _find_split(token: str) -> tuple[str, str] | None:
    """If one space insertion yields two valid parts, return (left, right); else None."""
    if len(token) < 3 or len(token) > MAX_TOKEN_LEN:
        return None
    dic = get_english_dictionary()
    if is_valid_word_for_rules(token, dic):  # type: ignore[arg-type]
        return None  # whole token is valid for rules; do not suggest split (e.g. "the" -> not "t he")
    for i in range(1, len(token)):
        left = token[:i]
        right = token[i:]
        if is_valid_word_for_rules(left, dic) and _valid_right_part(right, dic):  # type: ignore[arg-type]
            return (left, right)
    return None


def get_concatenated_word_split_form(token: str) -> str | None:
    """Return 'left right' if token splits into two valid parts; else None."""
    split = _find_split(token)
    if split is None:
        return None
    return f"{split[0]} {split[1]}"


def scan_turn_concatenated_word(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (concatenated_word_split, start_index, span, path_str) for tokens that split into two valid parts."""
    result: list[tuple[str, int, str, str]] = []
    dic = get_english_dictionary()
    for m in WORD_RE.finditer(text):
        token = m.group(1)
        if is_valid_word_for_rules(token, dic):  # type: ignore[arg-type]
            continue
        if _find_split(token) is not None:
            result.append(("concatenated_word_split", m.start(), token, path_str))
    return result
